/* Facebook DNA — feed gray, white cards, the blue, dense social chrome */
.theme-facebook-dna {
  --bg: oklch(0.960 0.005 258.3);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.921 0.008 260.7);
  --fg: oklch(0.115 0 0);
  --fg-muted: oklch(0.513 0.007 264.5);
  --accent: oklch(0.564 0.240 261.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.687 0.204 140.7);
  --line: oklch(0.896 0.006 255.5);
  --success: oklch(0.687 0.204 140.7);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.645 0.228 25.1);
  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Onest", "Helvetica Neue", sans-serif;
  --font-body: "Onest", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-facebook-dna h1,
.theme-facebook-dna h2,
.theme-facebook-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-facebook-dna { --font-ui: var(--font-display); }
.theme-facebook-dna h1 { font-weight: 700; letter-spacing: -0.02em; }
.theme-facebook-dna button { font-weight: 600; }

/* alt mode: auto-derived dark variant */
.theme-facebook-dna.alt-mode {
  --bg: oklch(0.145 0.005 258.3);
  --surface: oklch(0.185 0.005 258.3);
  --surface-2: oklch(0.225 0.005 258.3);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
